CREATE OR REPLACE FUNCTION public.sms_send_protection_verdict(_campaign uuid, _message uuid, _phone text)
 RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$ SELECT CASE WHEN _phone !~ '^\+[1-9][0-9]{6,14}$' THEN 'invalid_number' WHEN _phone LIKE '+1%' AND _phone !~ '^\+1[2-9][0-9]{2}[2-9][0-9]{6}$' THEN 'invalid_number' WHEN EXISTS(SELECT 1 FROM public.sms_invalid_destinations i WHERE i.account_id=c.account_id AND i.phone_e164=_phone) THEN 'invalid_number' WHEN EXISTS(SELECT 1 FROM public.suppressions s WHERE s.account_id=c.account_id AND s.phone_e164=_phone) THEN 'opted_out' WHEN (CASE c.smart_sending_mode WHEN 'on' THEN true WHEN 'off' THEN false ELSE a.smart_sending_enabled END) AND EXISTS(SELECT 1 FROM public.sms_phone_history h WHERE h.account_id=c.account_id AND h.phone_e164=_phone AND h.last_message_id<>_message AND h.last_sent_at>now()-make_interval(hours=>CASE WHEN c.smart_sending_mode='inherit' THEN a.smart_sending_hours ELSE c.smart_sending_hours END)) THEN 'recently_messaged' ELSE 'ok' END FROM public.campaigns c JOIN public.accounts a ON a.id=c.account_id WHERE c.id=_campaign $function$;